import React from "react";
import { clsx } from "clsx";

import { ListClasses } from "../list.styles";

export const ListEmptyState = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ children, className, ...rest }, ref) => (
  <div ref={ref} className={clsx(ListClasses.emptyState, className)} {...rest}>
    {children}
  </div>
));
ListEmptyState.displayName = "List.EmptyState";
